using System;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Threading;

namespace DeskTasks {
 public class Card:Form {
  public State Data; TaskList list=new TaskList(); Label status=new Label(); CardHeader header=new CardHeader(); Label empty=new Label(); NotifyIcon tray; System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();Point drag;bool moving,quitting;string openDay;Form mini;EventWaitHandle revealSignal=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\DeskTaskAssistantReveal");int timerTicks; System.Windows.Forms.Timer midnight=new System.Windows.Forms.Timer(); public event EventHandler DayChanged;
  public Card(State data){Data=data;Text="今日任务 · 桌面小助手";Font=Theme.Font(9);ClientSize=new Size(392,620);MinimumSize=new Size(360,510);FormBorderStyle=FormBorderStyle.None;BackColor=Theme.Canvas;Padding=new Padding(5);TopMost=Data.Settings.Topmost;StartPosition=FormStartPosition.Manual;Icon=Theme.MakeIcon();DoubleBuffered=true;Theme.RoundWindow(this,22);
   Rectangle area=Screen.PrimaryScreen.WorkingArea;Location=new Point(area.Right-Width-20,area.Top+20);if(Data.Settings.X>=0&&Screen.AllScreens.Any(s=>s.WorkingArea.Contains(new Point(Data.Settings.X,Data.Settings.Y))))Location=new Point(Data.Settings.X,Data.Settings.Y);
   header.Dock=DockStyle.Top;header.MouseDown+=(o,e)=>{if(e.Button==MouseButtons.Left){if(e.X>header.Width-65&&e.Y<67){Collapse();return;}moving=true;drag=System.Windows.Forms.Cursor.Position;header.Capture=true;}};header.MouseMove+=(o,e)=>{if(moving){Point p=System.Windows.Forms.Cursor.Position;Location=new Point(Left+p.X-drag.X,Top+p.Y-drag.Y);drag=p;}};header.MouseUp+=(o,e)=>{moving=false;header.Capture=false;SavePosition();};
   var footer=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=106,Padding=new Padding(13,9,13,9),ColumnCount=2,RowCount=2};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));footer.RowStyles.Add(new RowStyle(SizeType.Percent,50));footer.RowStyles.Add(new RowStyle(SizeType.Percent,50));var complete=Button("更新完成数量",()=>Toggle());((ModernButton)complete).Primary=true;footer.Controls.Add(complete,0,0);footer.Controls.Add(Button("＋  任务与统计",()=>Manage()),1,0);footer.Controls.Add(Button("每日总结",()=>Summary()),0,1);footer.Controls.Add(Button("收起为小按钮",()=>Collapse()),1,1);foreach(Control c in footer.Controls){c.Dock=DockStyle.Fill;c.AutoSize=false;}
   status.Dock=DockStyle.Bottom;status.Height=32;status.Padding=new Padding(18,0,12,0);status.Font=Theme.Font(8);status.ForeColor=Theme.Muted;
   var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(12,0,12,0)};list.Dock=DockStyle.Fill;list.MouseClick+=(o,e)=>{if(e.Button==MouseButtons.Left&&list.IndexFromPoint(e.Location)>=0)Toggle();};list.KeyDown+=(o,e)=>{if(e.KeyCode==Keys.Space||e.KeyCode==Keys.Enter){Toggle();e.Handled=true;}};empty.Text="今天，从一件小事开始。\n\n点击下方「任务与统计」\n添加你的第一个目标";empty.TextAlign=ContentAlignment.MiddleCenter;empty.Font=Theme.Font(11);empty.ForeColor=Theme.Muted;empty.Dock=DockStyle.Fill;body.Controls.Add(list);body.Controls.Add(empty);
   var section=new Label{Dock=DockStyle.Top,Height=36,Text="今日清单",ForeColor=Theme.Muted,Font=Theme.Font(9,true),Padding=new Padding(20,8,0,0)};Controls.Add(body);Controls.Add(section);Controls.Add(status);Controls.Add(footer);Controls.Add(header);
   tray=new NotifyIcon{Icon=Icon,Text="桌面任务小助手",Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("显示今日任务",null,(o,e)=>Reveal());menu.Items.Add("任务与统计",null,(o,e)=>Manage());menu.Items.Add("每日总结",null,(o,e)=>Summary());menu.Items.Add("退出",null,(o,e)=>{quitting=true;Close();});tray.ContextMenuStrip=menu;tray.DoubleClick+=(o,e)=>Reveal();tray.BalloonTipClicked+=(o,e)=>Summary();
   FormClosing+=(o,e)=>{SavePosition();if(!quitting&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Collapse();}};ResizeEnd+=(o,e)=>SavePosition();Engine.AdvanceDay(Data,DateTime.Now);Save();RefreshCard();timer.Interval=1000;timer.Tick+=(o,e)=>{if(revealSignal.WaitOne(0))Reveal();if(Data.LastPlan!=Engine.Key(DateTime.Today)||++timerTicks%30==0)Tick();};timer.Start();midnight.Tick+=(o,e)=>{midnight.Stop();Tick();ArmMidnight();};ArmMidnight();Microsoft.Win32.SystemEvents.PowerModeChanged+=PowerChanged;Microsoft.Win32.SystemEvents.TimeChanged+=ClockChanged;Shown+=(o,e)=>Tick();
  }
  protected override void Dispose(bool disposing){if(disposing){Microsoft.Win32.SystemEvents.PowerModeChanged-=PowerChanged;Microsoft.Win32.SystemEvents.TimeChanged-=ClockChanged;midnight.Dispose();timer.Dispose();revealSignal.Dispose();if(tray!=null)tray.Dispose();if(mini!=null)mini.Dispose();}base.Dispose(disposing);}
  protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==0x84&&(int)m.Result==1){Point p=PointToClient(new Point(m.LParam.ToInt32()));if(p.X>=ClientSize.Width-17&&p.Y>=ClientSize.Height-17)m.Result=(IntPtr)17;}}
  public static Button Button(string text,Action action){var b=new ModernButton{Text=text,AutoSize=true,Height=34,MinimumSize=new Size(110,34),Margin=new Padding(4),Primary=text.StartsWith("保存")||text.StartsWith("添加")};b.Click+=(o,e)=>action();return b;}
  public void Save(){Store.Save(Data);}void SavePosition(){Data.Settings.X=Math.Max(0,Left);Data.Settings.Y=Math.Max(0,Top);Save();}
  public void Collapse(){if(mini==null||mini.IsDisposed){mini=new Form{Text="展开任务",FormBorderStyle=FormBorderStyle.None,Size=new Size(152,48),StartPosition=FormStartPosition.Manual,TopMost=true,ShowInTaskbar=false,BackColor=Theme.Purple};var expand=new ModernButton{Text="✓  展开今日任务",Dock=DockStyle.Fill,Primary=true};expand.Click+=(o,e)=>Reveal();mini.Controls.Add(expand);Theme.RoundWindow(mini,14);}Rectangle bounds=Screen.FromControl(this).WorkingArea;mini.Location=new Point(Math.Min(Math.Max(Left,bounds.Left),bounds.Right-mini.Width),Math.Min(Math.Max(Top,bounds.Top),bounds.Bottom-mini.Height));mini.Show();Hide();}
  public void Reveal(){if(mini!=null)mini.Hide();Show();WindowState=FormWindowState.Normal;Activate();}
  public void RefreshCard(){openDay=Engine.Key(DateTime.Today);var rows=Engine.Today(Data,DateTime.Today);string selected=list.SelectedItem==null?"":((TaskGroup)list.SelectedItem).Key;list.BeginUpdate();list.Items.Clear();foreach(TaskGroup i in TaskGroups.Today(Data,DateTime.Today)){list.Items.Add(i);if(i.Key==selected)list.SelectedIndex=list.Items.Count-1;}list.EndUpdate();empty.Visible=rows.Count==0;list.Visible=rows.Count>0;header.Done=rows.Count(i=>i.Done!="");header.Total=rows.Count;header.Subtitle=DateTime.Today.ToString("M月d日 dddd")+"  ·  "+Data.Settings.WorkStart+"–"+Data.Settings.WorkEnd;header.Invalidate();status.Text=Data.Projects.Any(p=>!p.Archived&&p.Deadline.CompareTo(openDay)<0&&Data.Items.Any(i=>i.ProjectId==p.Id&&i.Kind=="任务"&&i.Done==""))?"有目标已过截止日，请到任务中心调整。":rows.Count>0&&rows.All(i=>i.Done!="")?"今日计划已完成，给自己的努力一个肯定。":"点击任务修改已完成数量 · 同一任务合并显示";TopMost=Data.Settings.Topmost;}
  void Toggle(){if(list.SelectedItem==null)return;if(openDay!=Engine.Key(DateTime.Today)){Tick();return;}using(var dialog=new QuantityForm(this,(TaskGroup)list.SelectedItem))dialog.ShowDialog(this);RefreshCard();}
  void ArmMidnight(){midnight.Stop();midnight.Interval=Engine.MillisecondsUntilMidnight(DateTime.Now);midnight.Start();}
  void ClockChanged(object sender,EventArgs e){ResumeRefresh();}
  void PowerChanged(object sender,Microsoft.Win32.PowerModeChangedEventArgs e){if(e.Mode==Microsoft.Win32.PowerModes.Resume)ResumeRefresh();}
  void ResumeRefresh(){if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke(new Action(()=>{if(IsDisposed)return;Tick();ArmMidnight();}));}catch(InvalidOperationException){}}
  void Tick(){string today=Engine.Key(DateTime.Today);if(Engine.AdvanceDay(Data,DateTime.Now)){Save();RefreshCard();ArmMidnight();if(DayChanged!=null)DayChanged(this,EventArgs.Empty);}TimeSpan at;if(TimeSpan.TryParse(Data.Settings.SummaryTime,out at)&&DateTime.Now.TimeOfDay>=at&&Data.LastReminder!=today&&!Data.Journals.Any(j=>j.Date==today)){Data.LastReminder=today;Save();tray.ShowBalloonTip(12000,"该做今日总结了","记录今天的进展，也可以给未来的自己添加任务。点击打开总结。",ToolTipIcon.Info);Reveal();status.Text="总结时间到了，记录一下今天的进展吧。";}}
  public void Manage(){using(var f=new Manager(this))f.ShowDialog(this);RefreshCard();}public void Summary(){using(var f=new SummaryForm(this))f.ShowDialog(this);RefreshCard();}
 }
